{"file_path": "C:/Users/UserX/.zcode/workspace/default/mcp_stdio_probe.mjs", "content": "// Minimal stdio JSON-RPC probe for an MCP server: initialize -> tools/list -> resources/list
import { spawn } from "node:child_process";

const [cmd, ...args] = process.argv.slice(2);
const child = spawn(cmd, args, { cwd: process.env.PROBE_CWD || process.cwd(), stdio: ["pipe", "pipe", "pipe"] });

let buf = "";
const results = {};
child.stdout.on("data", (d) => {
  buf += d.toString();
  let idx;
  while ((idx = buf.indexOf("\n")) >= 0) {
    const line = buf.slice(0, idx).trim();
    buf = buf.slice(idx + 1);
    if (!line) continue;
    try {
      const msg = JSON.parse(line);
      if (msg.id === 1) results.init = msg;
      if (msg.id === 2) results.tools = msg;
      if (msg.id === 3) results.resources = msg;
    } catch { /* ignore non-JSON stdout noise */ }
  }
});

child.stderr.on("data", (d) => process.stderr.write("[server stderr] " + d.toString()));

const send = (o) => child.stdin.write(JSON.stringify(o) + "\n");
send({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2026-07-28", capabilities: {}, clientInfo: { name: "probe", version: "1.0" } } });

setTimeout(() => {
  send({ jsonrpc: "2.0", method: "notifications/initialized" });
  send({ jsonrpc: "2.0", id: 2, method: "tools/list" });
  send({ jsonrpc: "2.0", id: 3, method: "resources/list" });
}, 1500);

setTimeout(() => {
  const t = results.tools?.result?.tools ?? [];
  const r = results.resources?.result?.resources ?? [];
  console.log("INIT:", JSON.stringify(results.init?.result?.serverInfo ?? results.init ?? null));
  console.log("TOOL COUNT:", t.length);
  console.log("FIRST 12 TOOLS:", t.slice(0, 12).map((x) => x.name).join(", "));
  console.log("RESOURCE COUNT:", r.length);
  console.log("RESOURCES:", r.map((x) => x.uri).slice(0, 14).join(", "));
  child.kill();
  process.exit(0);
}, 5000);
"}

