{"file_path": "C:/Users/UserX/.zcode/workspace/default/mcp_call.mjs", "content": "// MCP stdio client: initialize, then run a scripted sequence of tools/call, printing each result.
import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";

const [cmd, ...rest] = process.argv.slice(2);
const args = rest.slice(0, -1);
const scriptPath = rest[rest.length - 1];
const calls = JSON.parse(readFileSync(scriptPath, "utf8")); // [{tool, params}]

const child = spawn(cmd, args, { cwd: process.env.PROBE_CWD || process.cwd(), stdio: ["pipe", "pipe", "pipe"] });
let buf = "";
const pending = new Map();
child.stdout.on("data", (d) => {
  buf += d.toString();
  let i;
  while ((i = buf.indexOf("\n")) >= 0) {
    const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1);
    if (!line) continue;
    let msg; try { msg = JSON.parse(line); } catch { console.log("[non-JSON stdout]", line.slice(0, 200)); continue; }
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  }
});
child.stderr.on("data", (d) => process.stderr.write("[server stderr] " + d.toString()));
const send = (o) => child.stdin.write(JSON.stringify(o) + "\n");
const rpc = (id, method, params) => new Promise((res) => { pending.set(id, res); send({ jsonrpc: "2.0", id, method, params }); });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

await rpc(1, "initialize", { protocolVersion: "2026-07-28", capabilities: {}, clientInfo: { name: "probe", version: "1.0" } });
send({ jsonrpc: "2.0", method: "notifications/initialized" });
await sleep(300);

let id = 10;
for (const c of calls) {
  const r = await rpc(id++, "tools/call", { name: c.tool, arguments: c.params ?? {} });
  const txt = r.result?.content?.map((x) => x.text).join("\n") ?? JSON.stringify(r.error ?? r.result);
  console.log(`\n===== ${c.tool} =====`);
  console.log(txt.slice(0, c.max ?? 900));
}
child.kill();
process.exit(0);
"}

{"file_path": "C:/Users/UserX/.zcode/workspace/default/mcp_schema.mjs", "content": "// Dump inputSchema for named tools from an MCP stdio server: node mcp_schema.mjs <cmd> <args...> <script.py> tool1 tool2 ...
import { spawn } from "node:child_process";

const argv = process.argv.slice(2);
const wanted = argv.filter((a) => !a.includes("/") && !a.includes("\\") && !a.endsWith(".exe") && !a.endsWith(".py") && !a.endsWith(".mjs"));
const runner = argv.filter((a) => !wanted.includes(a));
const [cmd, ...args] = runner;

const child = spawn(cmd, args, { cwd: process.env.PROBE_CWD || process.cwd(), stdio: ["pipe", "pipe", "pipe"] });
let buf = ""; const pending = new Map();
child.stdout.on("data", (d) => {
  buf += d.toString(); let i;
  while ((i = buf.indexOf("\n")) >= 0) {
    const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1);
    if (!line) continue;
    let msg; try { msg = JSON.parse(line); } catch { continue; }
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  }
});
const send = (o) => child.stdin.write(JSON.stringify(o) + "\n");
const rpc = (id, method, params) => new Promise((r) => { pending.set(id, r); send({ jsonrpc: "2.0", id, method, params }); });

await rpc(1, "initialize", { protocolVersion: "2026-07-28", capabilities: {}, clientInfo: { name: "probe", version: "1.0" } });
send({ jsonrpc: "2.0", method: "notifications/initialized" });
const r = await rpc(2, "tools/list");
for (const t of r.result.tools) {
  if (!wanted.includes(t.name)) continue;
  console.log("\n### " + t.name + " — " + (t.description || "").split("\n")[0].slice(0, 160));
  const props = t.inputSchema?.properties ?? {};
  const req = t.inputSchema?.required ?? [];
  for (const [k, v] of Object.entries(props)) {
    console.log(`  - ${k}${req.includes(k) ? "*" : ""}: ${JSON.stringify(v).slice(0, 260)}`);
  }
}
child.kill(); process.exit(0);
"}

