const cyl = (faces.match(/cylind/i) ?? []).length;
console.log(`\n--- cylindrical faces by radius (${cyl} cylindrical) ---`);
console.log([...byR.entries()].sort((a, b) => b[0] - a[0]).map(([r, n]) => `r=${r} mm x${n}`).join(" | "));

console.log("\n--- save ---\n" + await call("save_document", { file_path: PART }));
child.kill(); process.exit(0);
"}

{"file_path": "C:/Users/UserX/.zcode/workspace/default/solidworks-gear/shot.ps1", "content": "# Bring SolidWorks forward, set an isometric + zoom-to-fit view, and capture its window to a PNG.
