{"file_path": "C:/Users/UserX/.zcode/workspace/default/solidworks-gear/pixel_probe.mjs", "content": "// Inspect the screenshot: brightness profile across the middle row, to design a part/background threshold.
import sharp from "sharp";
const img = sharp("C:/Users/UserX/.zcode/workspace/default/solidworks-gear/gear_front.png");
const { width: W, height: H } = await img.metadata();
const { data, info } = await img.removeAlpha().raw().toBuffer({ resolveWithObject: true });
const ch = info.channels;
const lum = (x, y) => { const i = (y * W + x) * ch; return (data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114) | 0; };
console.log(`image ${W}x${H}, channels=${ch}`);
const y0 = H >> 1;
let row = "";
for (let x = 0; x < W; x += 20) row += String(lum(x, y0)).padStart(4) + " ";
console.log("middle row luminance (every 20 px):\n" + row);
const colCount = {};
for (let y = 0; y < H; y += 3) for (let x = 0; x < W; x += 3) { const v = (lum(x, y) / 16) | 0; colCount[v] = (colCount[v] ?? 0) + 1; }
console.log("\nluminance histogram (bucket=16):", Object.entries(colCount).sort((a, b) => a[0] - b[0]).map(([k, v]) => `${k * 16}:${v}`).join(" "));
"}

{"file_path": "C:/Users/UserX/.zcode/workspace/default/solidworks-gear/pixel_verify.mjs", "content": "// Verify the rendered gear from the FRONT-view screenshot, in pixels:
//  1) ASCII silhouette so the shape is readable as text
//  2) count teeth on the pitch circle (Ø40) — must be 20
//  3) measure tip-circle Ø (should be 44 mm) and bore/lightening-hole diameters
import sharp from "sharp";
const FILE = "C:/Users/UserX/.zcode/workspace/default/solidworks-gear/gear_front.png";
const X0 = 430;                                   // skip the feature-tree panel
const img = sharp(FILE).removeAlpha();
const { width: W, height: H } = await img.metadata();
const { data, info } = await img.raw().toBuffer({ resolveWithObject: true });
const ch = info.channels;
const lum = (x, y) => { const i = (y * W + x) * ch; return data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114; };

// part vs background: the shaded part sits below ~237 luminance, the gradient background above
const TH = 237;
const isPart = (x, y) => lum(x, y) < TH;

let minX = W, maxX = 0, minY = H, maxY = 0;
for (let y = 0; y < H; y += 2) for (let x = X0; x < W; x += 2) if (isPart(x, y)) {
  if (x < minX) minX = x; if (x > maxX) maxX = x; if (y < minY) minY = y; if (y > maxY) maxY = y;
}
const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
const scale = (maxX - minX) / 44;                  // px per mm — the silhouette box is the Ø44 tip circle
console.log(`silhouette bbox x[${minX},${maxX}] y[${minY},${maxY}]  center=(${cx.toFixed(0)},${cy.toFixed(0)})  scale=${scale.toFixed(3)} px/mm  => tip Ø=${(((maxX - minX) + (maxY - minY)) / 2 / scale).toFixed(2)} mm`);

// ASCII silhouette (1 char ≈ 3 px), downsampled
const CW = 46, CHH = 22;
let art = "";
for (let r = 0; r < CHH; r++) {
  let line = "";
  for (let c = 0; c < CW; c++) {
    const x = minX + ((maxX - minX) * c) / (CW - 1), y = minY + ((maxY - minY) * r) / (CHH - 1);
    let hits = 0, n = 0;
    for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) { n++; if (isPart(Math.round(x + dx), Math.round(y + dy))) hits++; }
    line += hits / n > 0.6 ? "#" : hits / n > 0.25 ? "+" : ".";
  }
  art += line + "\n";
}
console.log("\nfront-view silhouette:\n" + art);

// teeth: walk the pitch circle (r = 20 mm) and count part/background transitions
const countRuns = (rMM, phase = 0) => {
  const r = rMM * scale;
  let runs = 0, prev = null;
  for (let i = 0; i < 3600; i++) {
    const a = (i / 3600) * Math.PI * 2 + phase;
    const x = Math.round(cx + r * Math.cos(a)), y = Math.round(cy - r * Math.sin(a));
    const p = isPart(x, y);
    if (prev !== null && p !== prev && p) runs++;
    prev = p;
  }
  return runs;
};
console.log(`teeth counted on Ø${(20 * 2)} pitch circle: ${[19, 19.5, 20, 20.5, 21].map((r) => `r${r}=${countRuns(r)}`).join(" ")}  (expect 20 material runs)`);
console.log(`teeth counted on Ø${(22 * 2)} tip circle  : r21.5=${countRuns(21.5)}  (expect 20)`);

// radial profile from the centre: bore Ø, hole band, root Ø — sampled along +X
let prof = [];
for (let rMM = 0; rMM <= 23; rMM += 0.5) {
  const x = Math.round(cx + rMM * scale), y = Math.round(cy);
  prof.push(`${rMM}:${isPart(x, y) ? "#" : "."}`);
}
console.log("\nradial part/void profile along +X (0..23 mm):\n" + prof.join(" "));
"}

